      }

      // We've reached a fixed point and all args are checked!
      Left(AppCandidate(resultArrow,
                        sargs,
                        newArgs.map(_.left.get),
                        preCandidate.overloading,
                        preCandidate.fnl))
    }
  }

  // Do the recursion to check the args.
  recurOnArgs(args)
}

